from pathlib import Path
import ast,json,hashlib,shutil,markdown
R=Path(__file__).resolve().parents[1];O=R/'doc/research/possible-bodies';E=R/'doc/space/ca-soft-rules-review-2026-09-14';RUN=R/'ada_run/ca-soft-rules-review-2026-09-14';M=R/'commons/maps/CA_SoftRules'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,s):
 p.parent.mkdir(parents=True,exist_ok=True);t=p.with_name(p.name+'.tmp');t.write_bytes((s.strip()+'\n').encode());t.replace(p)
